function setupBusinessChrome(audio) {
    const nav = document.querySelector('#business-nav'),
        panel = document.querySelector('#mobile-menu'),
        toggle = document.querySelector('#menu-toggle');
    let open = false,
        previousAction = false;
    const close = () => {
        open = false;
        panel.hidden = true;
        toggle.setAttribute('aria-expanded', 'false');
        document.body.classList.remove('menu-open');
    };
    toggle.addEventListener('click', () => {
        open = !open;
        panel.hidden = !open;
        toggle.setAttribute('aria-expanded', String(open));
        document.body.classList.toggle('menu-open', open);
    });
    document.querySelector('#menu-close').addEventListener('click', close);
    addEventListener('keydown', ev => {
        if (ev.key === 'Escape') {
            close();
            document.querySelectorAll('.currency-toggle').forEach(button => setNavDropdown(button, false));
        }
    });
    addEventListener('wheel', ev => {
        if (open) ev.preventDefault();
    }, {
        capture: true,
        passive: false
    });
    panel.addEventListener('touchmove', ev => ev.stopPropagation(), {
        passive: false
    });
    document.addEventListener('click', ev => {
        const button = ev.target.closest('button,[role=link]');
        if (button && !button.matches('#mute-toggle,[data-mode],[data-route-link]') && !button.closest('#scene-rail')) {
            ev.preventDefault();
            audio.click();
        }
    });
    document.addEventListener('click', ev => {
        if (!ev.target.closest('.currency')) document.querySelectorAll('.currency-toggle').forEach(button => setNavDropdown(button, false));
    });

    function alignCurrency() {
        const ctx = document.createElement('canvas').getContext('2d');
        document.querySelectorAll('.currency-label').forEach(el => {
            const css = getComputedStyle(el);
            ctx.font = css.font;
            const cap = ctx.measureText('USD'),
                x = ctx.measureText('x');
            const shift = (cap.fontBoundingBoxAscent - cap.fontBoundingBoxDescent - (cap.actualBoundingBoxAscent + x.actualBoundingBoxAscent) / 2) / 2;
            el.style.transform = 'translateY(' + (-shift) + 'px)';
        });
    }
    document.fonts.ready.then(alignCurrency);
    addEventListener('resize', alignCurrency);
    const stage = document.querySelector('#stage');
    return {
        update(p, instant = false) {
            if (window.__entryChromeFading) {
                nav.style.pointerEvents = 'none';
                return;
            }
            const action = p >= 1,
                opacity = action ? 1 : 1 - Math.min(1, p / .8);
            if (action !== previousAction) {
                previousAction = action;
                Us.killTweensOf(nav);
                if (action && !instant) {
                    Us.fromTo(nav, {
                        opacity: 0
                    }, {
                        opacity: 1,
                        duration: 1.25,
                        ease: 'power2.out'
                    });
                } else nav.style.opacity = opacity;
            }
            if (!action || instant) nav.style.opacity = opacity;
            nav.style.pointerEvents = opacity > .01 ? 'auto' : 'none';
            nav.classList.toggle('nav-dark', action);
            document.body.classList.toggle('action-scene', action);
            if (opacity <= .01 && !action) close();
            document.querySelector('.action-footer')?.style.setProperty('--rest-opacity', '1');
        },
        close
    };
}
